create table if not exists public.admin_internal_alerts(id uuid primary key default gen_random_uuid(), alert_key text unique not null, category text not null, severity text not null check(severity in('info','warning','critical')), title text not null, details jsonb not null default '{}'::jsonb, status text not null default 'open' check(status in('open','resolved')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.admin_internal_alerts enable row level security;
create or replace function public.admin_refresh_internal_alerts() returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_admin_role('admin') then raise exception 'admin_role_required'; end if;
 insert into public.admin_internal_alerts(alert_key,category,severity,title,details) select 'payments_pending','payments','warning','Pagamentos pendentes',jsonb_build_object('count',count(*)) from public.payment_history where status='pending' having count(*)>0 on conflict(alert_key) do update set details=excluded.details,status='open',updated_at=now();
 insert into public.admin_internal_alerts(alert_key,category,severity,title,details) select 'subscriptions_cancelled_30d','payments','info','Cancelamentos recentes',jsonb_build_object('count',count(*)) from public.user_subscriptions where cancelled_at>=now()-interval '30 days' having count(*)>0 on conflict(alert_key) do update set details=excluded.details,status='open',updated_at=now();
 insert into public.admin_internal_alerts(alert_key,category,severity,title,details) select 'ai_high_usage_24h','ai','warning','Alto consumo de IA',jsonb_build_object('requests',count(*)) from public.ai_usage where status='completed' and created_at>=now()-interval '24 hours' having count(*)>=100 on conflict(alert_key) do update set details=excluded.details,status='open',updated_at=now();
 insert into public.admin_internal_alerts(alert_key,category,severity,title,details) select 'gemini_failures_30m','ai','critical','Falhas repetidas do Gemini/IA',jsonb_build_object('failures',count(*),'window','30 minutos') from public.ai_usage where status='released' and created_at>=now()-interval '30 minutes' having count(*)>=3 on conflict(alert_key) do update set details=excluded.details,status='open',updated_at=now();
 insert into public.admin_internal_alerts(alert_key,category,severity,title,details) select 'ai_near_quota','ai','warning','Usuários próximos da cota mensal',jsonb_build_object('users',count(*)) from (select usage.user_id from public.ai_usage usage join public.user_subscriptions s on s.id=usage.subscription_id join public.subscription_plans p on p.code=s.plan_code where usage.status in('reserved','completed') and usage.period_start=s.current_period_start group by usage.user_id,p.monthly_ai_credits having sum(usage.credits_used)>=p.monthly_ai_credits*.8) x having count(*)>0 on conflict(alert_key) do update set details=excluded.details,status='open',updated_at=now(); end $$;
create or replace function public.admin_list_internal_alerts() returns table(id uuid,category text,severity text,title text,details jsonb,status text,created_at timestamptz) language plpgsql security definer set search_path=public as $$ begin if not public.has_admin_role('admin') then raise exception 'admin_role_required'; end if; perform public.admin_refresh_internal_alerts(); return query select a.id,a.category,a.severity,a.title,a.details,a.status,a.created_at from public.admin_internal_alerts a where a.status='open' order by case a.severity when 'critical' then 1 when 'warning' then 2 else 3 end,a.updated_at desc; end $$;
grant execute on function public.admin_refresh_internal_alerts() to authenticated; grant execute on function public.admin_list_internal_alerts() to authenticated;
